const input = $json.body || $json;
const phone = input.to_number || input.to_phone || input.phone;
const leadId = input.lead_id || (input.call_context ? input.call_context.lead_id : `lead_${Date.now()}`);
const businessName = input.business_name || (input.call_context ? input.call_context.business_name : 'Valued Business');
const category = input.category || (input.call_context ? input.call_context.category : 'Commercial Services');
const city = input.city || (input.call_context ? input.call_context.city : 'Local Area');

return [{
  json: {
    agent_id: process.env.OMNIDIM_AGENT_ID || '4cd9f881-58f7-4969-876a-00983214c362',
    to_number: phone,
    welcome_message: `Hi ${businessName}, this is the AI assistant for a local web development service. Am I speaking with the business owner?`,
    call_context: {
      lead_id: leadId,
      business_name: businessName,
      category: category,
      city: city
    },
    metadata: {
      crm_lead_id: leadId,
      source: 'sales_portal'
    }
  }
}];
